-- =============================================
-- GADYS - Novos locais adicionados
-- Páginas específicas criadas em 2025
-- =============================================

-- PIAUÍ
INSERT INTO Localizacao (nome, descricao, categoria, subcategoria, cidade, estado, status, enviado_por) VALUES
('Serra da Capivara', 'Patrimônio Mundial da UNESCO com mais de 1.300 sítios arqueológicos e pinturas rupestres de até 50 mil anos — o maior acervo de arte pré-histórica das Américas.', 'lugares-visitar', 'lugares-paradisiacos', 'São Raimundo Nonato', 'Piauí', 'ATIVO', 'GADYS'),
('Delta do Parnaíba', 'O único delta em mar aberto das Américas, com 70 ilhas, manguezais, dunas e uma fauna exuberante entre os rios Parnaíba e o Oceano Atlântico.', 'lugares-visitar', 'lugares-paradisiacos', 'Parnaíba', 'Piauí', 'ATIVO', 'GADYS'),
('Parque Nacional Sete Cidades', 'Formações rochosas milenares que lembram ruínas de cidades antigas, com inscrições rupestres e trilhas por um cenário geológico único no mundo.', 'lugares-visitar', 'lugares-paradisiacos', 'Piracuruca', 'Piauí', 'ATIVO', 'GADYS'),
('Luís Correia', 'Praias desertas, dunas, lagoas de água doce e o encontro do Rio Parnaíba com o mar formam um dos litorais mais selvagens e preservados do Nordeste.', 'lugares-visitar', 'lugares-paradisiacos', 'Luís Correia', 'Piauí', 'ATIVO', 'GADYS'),
('Pedra do Castelo', 'Imponente formação rochosa no sertão piauiense que se assemelha a um castelo medieval, cercada por uma paisagem árida e mística.', 'lugares-visitar', 'lugares-paradisiacos', 'Queimada Nova', 'Piauí', 'ATIVO', 'GADYS'),
('Centro Histórico de Teresina', 'A única capital brasileira fundada no Império, com o Theatro 4 de Setembro, o Museu do Piauí e o encontro dos rios Parnaíba e Poti.', 'lugares-visitar', 'monumentos', 'Teresina', 'Piauí', 'ATIVO', 'GADYS');

-- RIO GRANDE DO NORTE
INSERT INTO Localizacao (nome, descricao, categoria, subcategoria, cidade, estado, status, enviado_por) VALUES
('Dunas de Genipabu', 'Um deserto dourado à beira-mar: dunas gigantes, lagoas de água doce e o famoso passeio de buggy e dromedário a apenas 25 km de Natal.', 'lugares-visitar', 'lugares-paradisiacos', 'Extremoz', 'Rio Grande do Norte', 'ATIVO', 'GADYS'),
('Praia de Pipa', 'Falésias avermelhadas, águas cristalinas e golfinhos na Baía dos Golfinhos fazem de Pipa um dos destinos mais charmosos do litoral nordestino.', 'lugares-visitar', 'lugares-paradisiacos', 'Tibau do Sul', 'Rio Grande do Norte', 'ATIVO', 'GADYS'),
('Maracajaú', 'Considerado o maior aquário natural do Brasil, com piscinas naturais de águas mornas e transparentes, repletas de peixes coloridos e corais vivos.', 'lugares-visitar', 'lugares-paradisiacos', 'Maxaranguape', 'Rio Grande do Norte', 'ATIVO', 'GADYS'),
('Parque das Dunas', 'A maior área de proteção de dunas urbanas do mundo, com 1.172 hectares de Mata Atlântica no coração de Natal.', 'lugares-visitar', 'lugares-paradisiacos', 'Natal', 'Rio Grande do Norte', 'ATIVO', 'GADYS'),
('Forte dos Reis Magos', 'Construído pelos portugueses em 1598 em formato de estrela, é o marco zero de Natal e um dos fortes coloniais mais bem preservados do Brasil.', 'lugares-visitar', 'monumentos', 'Natal', 'Rio Grande do Norte', 'ATIVO', 'GADYS'),
('Baía Formosa', 'Praias desertas, falésias, manguezais e águas esverdeadas formam um dos litorais mais selvagens e preservados do Rio Grande do Norte.', 'lugares-visitar', 'lugares-paradisiacos', 'Baía Formosa', 'Rio Grande do Norte', 'ATIVO', 'GADYS');

-- RIO GRANDE DO SUL
INSERT INTO Localizacao (nome, descricao, categoria, subcategoria, cidade, estado, status, enviado_por) VALUES
('Gramado', 'A cidade mais encantadora do Brasil: arquitetura europeia, chocolate artesanal premiado, o Natal Luz e temperaturas negativas na Serra Gaúcha a 825 m de altitude.', 'lugares-visitar', 'lugares-paradisiacos', 'Gramado', 'Rio Grande do Sul', 'ATIVO', 'GADYS'),
('Cânion Itaimbezinho', 'Um dos maiores cânions do mundo, com paredes de arenito de até 720 m de altura e 5,8 km de extensão no Parque Nacional dos Aparados da Serra.', 'lugares-visitar', 'lugares-paradisiacos', 'Cambará do Sul', 'Rio Grande do Sul', 'ATIVO', 'GADYS'),
('Bento Gonçalves', 'Capital brasileira do vinho, com vinhedos centenários, adegas premiadas, a Maria Fumaça e a culinária italiana herdada dos imigrantes.', 'lugares-visitar', 'lugares-paradisiacos', 'Bento Gonçalves', 'Rio Grande do Sul', 'ATIVO', 'GADYS'),
('Porto Alegre', 'Capital gaúcha às margens do Guaíba, com o pôr do sol mais bonito do Brasil, o Mercado Público histórico e uma cena cultural vibrante.', 'lugares-visitar', 'monumentos', 'Porto Alegre', 'Rio Grande do Sul', 'ATIVO', 'GADYS'),
('Torres', 'Praias com falésias basálticas únicas no Brasil, grutas, ilhas e o Parque Estadual de Torres formam um dos litorais mais dramáticos do sul do país.', 'lugares-visitar', 'lugares-paradisiacos', 'Torres', 'Rio Grande do Sul', 'ATIVO', 'GADYS'),
('São Miguel das Missões', 'Ruínas jesuíticas do século XVII e Patrimônio Mundial da UNESCO. O espetáculo de som e luz noturno sobre as ruínas é uma das experiências mais marcantes do Brasil.', 'lugares-visitar', 'monumentos', 'São Miguel das Missões', 'Rio Grande do Sul', 'ATIVO', 'GADYS');

-- SANTA CATARINA
INSERT INTO Localizacao (nome, descricao, categoria, subcategoria, cidade, estado, status, enviado_por) VALUES
('Florianópolis', 'A Ilha da Magia: mais de 100 praias, lagoas de água doce, dunas e uma rica herança açoriana que fazem de Florianópolis um dos destinos mais encantadores do Brasil.', 'lugares-visitar', 'lugares-paradisiacos', 'Florianópolis', 'Santa Catarina', 'ATIVO', 'GADYS'),
('Balneário Camboriú', 'A cidade com o segundo maior arranha-céu do mundo, praias de águas calmas, o Bondês do Morro e uma vida noturna que a tornaram a "Dubai brasileira".', 'lugares-visitar', 'lugares-paradisiacos', 'Balneário Camboriú', 'Santa Catarina', 'ATIVO', 'GADYS'),
('Bombinhas', 'Considerada a cidade com as águas mais transparentes do Brasil, com praias paradisíacas, mergulho com golfinhos e a Reserva Biológica Marinha do Arvoredo.', 'lugares-visitar', 'lugares-paradisiacos', 'Bombinhas', 'Santa Catarina', 'ATIVO', 'GADYS'),
('Blumenau', 'A capital catarinense da cultura alemã realiza a segunda maior Oktoberfest do mundo, com cerveja artesanal e arquitetura enxaimel.', 'lugares-visitar', 'monumentos', 'Blumenau', 'Santa Catarina', 'ATIVO', 'GADYS'),
('São Joaquim', 'A cidade mais fria do Brasil, famosa pela neve no inverno, maçãs premiadas, vinhos de altitude e paisagens de tirar o fôlego na Serra Catarinense.', 'lugares-visitar', 'lugares-paradisiacos', 'São Joaquim', 'Santa Catarina', 'ATIVO', 'GADYS'),
('Joinville', 'A maior cidade de Santa Catarina e capital do Festival de Dança, o maior evento de dança do mundo, com herança alemã e uma cena cultural vibrante.', 'lugares-visitar', 'monumentos', 'Joinville', 'Santa Catarina', 'ATIVO', 'GADYS');

-- SÃO PAULO
INSERT INTO Localizacao (nome, descricao, categoria, subcategoria, cidade, estado, status, enviado_por) VALUES
('MASP', 'O Museu de Arte de São Paulo, projetado por Lina Bo Bardi em 1968, é um dos mais importantes da América Latina com mais de 11 mil obras e arquitetura icônica.', 'lugares-visitar', 'monumentos', 'São Paulo', 'São Paulo', 'ATIVO', 'GADYS');

-- SERGIPE
INSERT INTO Localizacao (nome, descricao, categoria, subcategoria, cidade, estado, status, enviado_por) VALUES
('Cânion do Xingó', 'Um dos espetáculos naturais mais impressionantes do Nordeste, com paredes rochosas de até 150 metros e as águas esverdeadas do Rio São Francisco.', 'lugares-visitar', 'lugares-paradisiacos', 'Canindé de São Francisco', 'Sergipe', 'ATIVO', 'GADYS');

-- RORAIMA
INSERT INTO Localizacao (nome, descricao, categoria, subcategoria, cidade, estado, status, enviado_por) VALUES
('Parque Nacional do Monte Roraima', 'O parque protege os tepuis e a savana do Lavrado, com biodiversidade única e paisagens que inspiraram Arthur Conan Doyle a escrever "O Mundo Perdido".', 'lugares-visitar', 'lugares-paradisiacos', 'Pacaraima', 'Roraima', 'ATIVO', 'GADYS'),
('Lavrado de Roraima', 'A maior savana amazônica do mundo, com campos abertos, buritizais e lagoas sazonais que abrigam espécies endêmicas únicas no planeta.', 'lugares-visitar', 'lugares-paradisiacos', 'Boa Vista', 'Roraima', 'ATIVO', 'GADYS');

-- RONDÔNIA
INSERT INTO Localizacao (nome, descricao, categoria, subcategoria, cidade, estado, status, enviado_por) VALUES
('Museu Estrada de Ferro Madeira-Mamoré', 'A "Ferrovia do Diabo", construída entre 1907 e 1912, preservada no museu de Porto Velho com locomotivas originais e a memória dos mais de 6.000 trabalhadores.', 'lugares-visitar', 'monumentos', 'Porto Velho', 'Rondônia', 'ATIVO', 'GADYS'),
('Lago de Samuel', 'Formado pela Usina Hidrelétrica de Samuel, o lago é um destino popular para pesca esportiva, passeios de barco e esportes aquáticos.', 'lugares-visitar', 'lugares-paradisiacos', 'Porto Velho', 'Rondônia', 'ATIVO', 'GADYS'),
('Catedral Nossa Senhora das Graças', 'A principal igreja de Porto Velho, com arquitetura imponente e vitrais coloridos, símbolo da fé e da história da capital rondoniense.', 'lugares-visitar', 'monumentos', 'Porto Velho', 'Rondônia', 'ATIVO', 'GADYS'),
('Reserva Biológica do Jaru', 'Uma das mais importantes reservas biológicas da Amazônia, com floresta primária preservada e fauna riquíssima, incluindo onças-pintadas e antas.', 'lugares-visitar', 'lugares-paradisiacos', 'Ji-Paraná', 'Rondônia', 'ATIVO', 'GADYS');

-- TOCANTINS
INSERT INTO Localizacao (nome, descricao, categoria, subcategoria, cidade, estado, status, enviado_por) VALUES
('Ilha do Bananal', 'A maior ilha fluvial do mundo, formada pelos rios Araguaia e Javaés, com praias fluviais paradisíacas e o Parque Nacional do Araguaia.', 'lugares-visitar', 'lugares-paradisiacos', 'Santa Terezinha', 'Tocantins', 'ATIVO', 'GADYS'),
('Orla de Palmas', 'A orla da capital às margens do Lago de Palmas, com praias fluviais, parques e vista deslumbrante da Serra do Lajeado.', 'lugares-visitar', 'lugares-paradisiacos', 'Palmas', 'Tocantins', 'ATIVO', 'GADYS'),
('Catedral Nossa Senhora da Assunção', 'A catedral de Palmas, com arquitetura moderna e imponente, símbolo da capital mais jovem do Brasil, inaugurada em 1989.', 'lugares-visitar', 'monumentos', 'Palmas', 'Tocantins', 'ATIVO', 'GADYS'),
('Cachoeira da Serra do Lajeado', 'A Serra do Lajeado abriga diversas cachoeiras e trilhas ecológicas com vistas panorâmicas da capital e do Lago de Palmas.', 'lugares-visitar', 'lugares-paradisiacos', 'Palmas', 'Tocantins', 'ATIVO', 'GADYS'),
('Feira Gastronômica de Palmas', 'A gastronomia tocantinense é uma fusão de sabores do Cerrado e da Amazônia, com pratos como peixe na telha, pequi com arroz e baru torrado.', 'curiosidades', 'restaurantes', 'Palmas', 'Tocantins', 'ATIVO', 'GADYS');

